.ds-site-nav { position: relative; z-index: 20; border-bottom: 1px solid var(--rule); background: var(--paper); }
.ds-site-nav__inner { max-width: var(--max-page); margin: auto; padding: 0 var(--gutter-desktop); height: var(--nav-h-desktop); display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.ds-desktop-nav { display: flex; align-items: center; gap: 32px; }
.ds-site-nav nav a { min-height: 44px; display: inline-flex; align-items: center; gap: 12px; color: var(--ink); text-decoration: none; font-size: 15px; font-weight: 500; }
.ds-site-nav nav a:hover, .ds-site-nav nav a[aria-current] { color: var(--blue); text-decoration: underline; text-underline-offset: 7px; }
.ds-site-nav nav .ds-nav-follow { padding-left: 30px; border-left: 1px solid var(--rule); color: var(--blue); }
.ds-mobile-menu { display: none; }
@media (max-width: 767.98px) {
  .ds-site-nav__inner { height: var(--nav-h-mobile); }
  .ds-desktop-nav { display: none; }
  .ds-mobile-menu { display: block; }
  .ds-site-nav summary { min-width: 88px; min-height: 44px; display: flex; align-items: center; justify-content: flex-end; gap: 10px; padding: 8px 0 8px 8px; cursor: pointer; list-style: none; font-size: 15px; }
  .ds-site-nav summary::-webkit-details-marker { display: none; }
  .ds-menu-label--close, .ds-mobile-menu[open] .ds-menu-label--open { display: none; }
  .ds-mobile-menu[open] .ds-menu-label--close { display: inline; }
  .ds-menu-stroke { transform-origin: 12px 12px; transition: transform 180ms var(--ease-out); }
  .ds-menu-stroke--one { transform: translateY(-4px); }
  .ds-menu-stroke--two { transform: translateY(4px); }
  .ds-mobile-menu[open] .ds-menu-stroke--one { transform: rotate(45deg); }
  .ds-mobile-menu[open] .ds-menu-stroke--two { transform: rotate(-45deg); }
  .ds-mobile-menu nav { position: absolute; top: 100%; left: 0; right: 0; padding: 12px 24px 20px; max-height: calc(100dvh - var(--nav-h-mobile)); overflow-y: auto; border-bottom: 1px solid var(--rule); background: var(--paper); box-shadow: var(--shadow-nav); }
  .ds-mobile-menu__primary { display: grid; }
  .ds-mobile-menu__primary a { padding: 10px 0; min-height: 56px; border-bottom: 1px solid var(--rule); font: 400 32px/1.2 var(--font-editorial); letter-spacing: -.02em; }
  .ds-mobile-menu__primary a:last-child { border-bottom: 0; }
  .ds-mobile-menu__secondary { display: flex; flex-wrap: wrap; gap: 4px 28px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--rule); }
  .ds-mobile-menu__secondary a { padding-block: 8px; min-height: 44px; font-size: 16px; }
  .ds-mobile-menu[open] nav { animation: rs-panel-enter 200ms var(--ease-out); }
}
@media (prefers-reduced-motion: reduce) {
  .ds-menu-stroke { transition: none; }
  .ds-mobile-menu[open] nav { animation: none; }
}

.ds-site-wordmark {
  display: inline-block;
  font: 400 32px/1.1 var(--font-editorial);
  letter-spacing: -.02em;
  word-spacing: .08em;
  white-space: nowrap;
}
.ds-site-wordmark__dot { color: var(--blue); letter-spacing: 0; word-spacing: 0; }


.ds-wordmark-link { display: inline-flex; align-items: center; min-height: 44px; padding-block: 6px; color: inherit; text-decoration: none; }

