.ds-reading-list.ds-compact li { grid-template-columns: minmax(0,1fr); gap: 12px; padding: 26px 0; }
.ds-reading-list.ds-compact .ds-reading-date { flex-direction: row; gap: 14px; padding: 0; }
.ds-reading-list.ds-compact h3 { font-size: 24px; }
.ds-reading-list.ds-paired { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); column-gap: 64px; }
.ds-reading-list.ds-paired li { padding-block: 28px; }
.ds-reading-list.ds-paired h3 { max-width: 28ch; font-size: 28px; letter-spacing: -.015em; }
@media (max-width: 767.98px) {
 .ds-reading-list li { grid-template-columns: minmax(0,1fr); gap: 12px; padding: 26px 0; }
