.ds-site-footer { background: var(--ink); color: var(--paper); padding: 56px 0 28px; }
.ds-footer-top { display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.ds-footer-top p { font-size: 20px; margin: 0; color: var(--on-dark-78); }
.ds-site-footer nav { display: flex; flex-wrap: wrap; gap: 12px 32px; padding: 32px 0 44px; }
.ds-site-footer a { color: var(--paper); display: inline-flex; align-items: center; gap: 8px; min-height: 44px; }
.ds-site-footer a:hover { color: var(--yellow); }
.ds-site-footer a:focus-visible { outline-color: var(--yellow); }
.ds-site-footer nav a { text-decoration: none; min-width: var(--tap-min); }
.ds-footer-bottom { border-top: 1px solid var(--on-dark-28); padding-top: 20px; display: flex; justify-content: space-between; align-items: center; gap: 16px; font-size: 13px; color: var(--on-dark-78); }
.ds-footer-bottom div { display: flex; gap: 24px; flex-wrap: wrap; }
.ds-footer-bottom a { color: inherit; }
.ds-site-footer.ds-quiet { background: var(--paper); color: var(--ink); }
.ds-site-footer.ds-quiet a { color: var(--ink); }
.ds-site-footer.ds-quiet a:hover { color: var(--ink); }
.ds-site-footer.ds-quiet a:focus-visible { outline-color: var(--focus-ring); }
.ds-site-footer.ds-quiet .ds-footer-top p, .ds-site-footer.ds-quiet .ds-footer-bottom { color: var(--ink-muted); }
.ds-site-footer.ds-quiet .ds-footer-bottom { border-color: var(--rule); }
@media (max-width: 767.98px) {
  .ds-footer-top, .ds-footer-bottom { align-items: flex-start; flex-direction: column; gap: 12px; }
  .ds-site-footer nav { gap: 4px 24px; padding: 24px 0; }
  .ds-footer-bottom div { gap: 4px 20px; }
}

.ds-site-wordmark {
