.ds-character-moment path { stroke-linecap: round; stroke-linejoin: round; }
.ds-moment-ground { stroke: var(--rule); stroke-width: 1; }
.ds-moment-furniture { stroke: var(--ink-muted); stroke-width: 2; }
.ds-moment-sign { fill: var(--paper-inset); stroke: var(--ink-muted); stroke-width: 1.5; }
.ds-moment-sign-arrow { stroke: var(--ink); stroke-width: 1.8; }
.ds-moment-prop { stroke: var(--ink); stroke-width: 2; fill: none; }
.ds-moment-laptop { stroke: var(--ink-muted); stroke-width: 3; }
.ds-moment-bookLeft, .ds-moment-bookRight, .ds-moment-map { fill: var(--paper); stroke-width: 1.5; }
.ds-moment-bookSpine, .ds-moment-bookLines { stroke: var(--ink-muted); stroke-width: 1; }
.ds-moment-mapRoute { stroke: var(--blue); stroke-width: 1.5; }
