.ds-runner-person .ds-runner-head { fill: var(--ink); }
.ds-runner-person .ds-runner-torso { fill: var(--blue); }
.ds-runner-neck { stroke: var(--ink); stroke-width: 5; }
.ds-runner-legBack { stroke: var(--ink-muted); stroke-width: 6; }
.ds-runner-legFront { stroke: var(--ink); stroke-width: 6; }
.ds-runner-armBack { stroke: var(--ink-muted); stroke-width: 4.5; }
.ds-runner-armFront { stroke: var(--ink); stroke-width: 4.5; }
